from pathlib import Path
import re
base=Path('/mnt/data/sitework')
idx=base/'index.html'
s=idx.read_text()
# Fix accidental invalid custom tag selectors from prior generated CSS by normalizing to classes.
s=s.replace('.web developments','.services-list').replace('.web development','.service-item')
s=s.replace('#web developments','#services')
s=s.replace('Web Development [4]','Services')
s=s.replace('Explore web developments ↗','Explore services ↗')
s=s.replace('Developer & Creator','Web Developer & Programmer')
s=s.replace('Designed & built with HTML, CSS & JavaScript · Web Development, journey & contact','Designed & built with HTML, CSS & JavaScript · Web Development & Python Programming')
# Replace the entire services section.
pat=r'<section class="panel section dark reveal" id="services">.*?</section>'
section='''<section class="panel section dark reveal" id="services"><div class="title"><div class="ghost">SERVICES</div><h2>SERVICES</h2><div class="meta">What I am learning & building</div></div><p class="services-note">Still learning and acquiring skills — building real projects every day to turn what I learn into practical work.</p><div class="services-list"><div class="service-item"><span class="no">01</span><div><h3>Web Development</h3><p>Responsive websites, interactive interfaces, landing pages and browser-based tools with smooth modern motion.</p></div><a class="service-demo" href="demos.html?type=web" aria-label="View web development demos">↗</a></div><div class="service-item"><span class="no">02</span><div><h3>Python Programming</h3><p>Practical Python programs, automation ideas, data tools and beginner-friendly problem solving.</p></div><a class="service-demo" href="demos.html?type=python" aria-label="View Python programming demos">↗</a></div></div><a class="cta demo-main" href="demos.html">See All Demo Projects ↗</a></section>'''
s=re.sub(pat,section,s,flags=re.S)
# Add service CSS before </style> in the first style block.
css='''
.services-note{max-width:720px;color:#9b9b96;font-size:12px;line-height:1.8;margin:-15px 0 28px}.services-list{border-top:1px solid #3a3a37}.service-item{display:grid;grid-template-columns:60px 1fr 30px;gap:20px;align-items:center;padding:28px 0;border-bottom:1px solid #3a3a37;transition:.65s cubic-bezier(.16,1,.3,1)}.service-item:hover{padding-left:12px;background:#292927}.service-item .no{font-size:10px;color:#777}.service-item h3{font:500 25px 'Space Grotesk';letter-spacing:-.05em;margin-bottom:6px}.service-item p{font-size:11px;line-height:1.7;color:#999;max-width:680px}.service-demo{font-size:20px;color:#999;transition:.45s cubic-bezier(.16,1,.3,1)}.service-item:hover .service-demo{color:#fff;transform:translate(4px,-4px)}.demo-main{margin-top:30px}
'''
s=s.replace('</style><style>',''+css+'</style><style>',1)
# If exact replacement didn't happen, append before first </style>.
if '.services-note' not in s.split('</style>',1)[0]:
    s=s.replace('</style>',css+'</style>',1)
# Mobile styles for services.
s=s.replace('@media(max-width:800px){', '@media(max-width:800px){.service-item{grid-template-columns:35px 1fr 20px}.service-item p{margin-top:4px}.services-note{margin-top:-5px}\n',1)
idx.write_text(s)

shared_css='''
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--paper:#f7f7f3;--ink:#171717;--line:#deded8;--dark:#232323;--green:#38d477;--ease:cubic-bezier(.16,1,.3,1)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:'DM Sans',sans-serif;background:#c8c9c6;color:var(--ink);overflow-x:hidden}body:before{content:"";position:fixed;inset:-15%;z-index:-5;background:radial-gradient(ellipse at 10% 20%,#fff 0 10%,transparent 30%),radial-gradient(ellipse at 88% 30%,#fff9 0 12%,transparent 33%),linear-gradient(125deg,#bfc0bd,#e2e3df,#bfc0bd);filter:blur(30px);animation:clouds 18s ease-in-out infinite alternate}@keyframes clouds{to{transform:translate(4%,2%) scale(1.06)}}a{text-decoration:none;color:inherit}.site{width:min(1180px,calc(100% - 42px));margin:22px auto 40px}.panel{background:var(--paper);margin-bottom:28px;border-radius:5px;overflow:hidden;box-shadow:0 35px 100px #0002}.nav{height:72px;padding:0 42px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e4e4df;position:sticky;top:0;background:#f7f7f3e8;backdrop-filter:blur(18px);z-index:30}.nav a{font-size:10px}.back{padding:10px 14px;border:1px solid #deded8;border-radius:99px}.back:hover{background:#171717;color:#fff}.hero2{padding:78px 55px 50px}.eyebrow{font-size:9px;letter-spacing:2px;text-transform:uppercase;color:#888}.hero2 h1{font:600 clamp(52px,8vw,96px)/.9 'Space Grotesk';letter-spacing:-.08em;margin:12px 0}.hero2 p{max-width:680px;color:#777;line-height:1.8;font-size:12px}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0 0}.filter{border:1px solid var(--line);background:transparent;border-radius:99px;padding:9px 13px;font-size:9px;cursor:pointer}.filter.active,.filter:hover{background:#171717;color:#fff}.grid{display:grid;grid-template-columns:repeat(2,1fr);border-top:1px solid var(--line)}.demo-card{padding:30px;border-bottom:1px solid var(--line);transition:.65s var(--ease);position:relative;overflow:hidden}.demo-card:nth-child(even){border-left:1px solid var(--line)}.demo-card:before{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent,#fff,transparent);transform:translateX(-120%);transition:1s}.demo-card:hover:before{transform:translateX(120%)}.demo-card:hover{transform:translateY(-5px);background:#fff}.tag{display:inline-block;background:#ecece7;color:#777;border-radius:99px;padding:5px 8px;font-size:8px;letter-spacing:.8px;text-transform:uppercase}.demo-card h2{font:500 28px 'Space Grotesk';letter-spacing:-.05em;margin:18px 0 8px}.demo-card p{font-size:11px;color:#777;line-height:1.7;min-height:58px}.demo-card .open{display:inline-flex;margin-top:20px;background:#171717;color:#fff;padding:11px 15px;border-radius:7px;font-size:10px;transition:.45s var(--ease)}.demo-card .open:hover{transform:translateY(-3px);box-shadow:0 12px 25px #0003}.demo-card.hidden{display:none}.footer{padding:22px 55px;color:#888;font-size:9px}@media(max-width:800px){.site{width:calc(100% - 18px);margin:9px auto 25px}.nav{padding:0 18px;height:64px}.hero2{padding:62px 22px 38px}.grid{grid-template-columns:1fr}.demo-card:nth-child(even){border-left:0}.footer{padding:18px 22px}}
'''
particle='''<script>(()=>{if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;const c=document.createElement('canvas');c.id='particles';document.body.prepend(c);const x=c.getContext('2d',{alpha:true});let w,h,d,ps=[];const m={x:-999,y:-999,tx:-999,ty:-999};function size(){d=Math.min(devicePixelRatio||1,2);w=innerWidth;h=innerHeight;c.width=w*d;c.height=h*d;c.style='position:fixed;inset:0;width:100%;height:100%;z-index:-3;pointer-events:none;opacity:.48';x.setTransform(d,0,0,d,0,0);ps=Array.from({length:w<700?42:78},()=>({x:Math.random()*w,y:Math.random()*h,vx:(Math.random()-.5)*.14,vy:(Math.random()-.5)*.14,r:.7+Math.random()*1.1,p:Math.random()*6.28}))}addEventListener('resize',size,{passive:true});addEventListener('pointermove',e=>{m.tx=e.clientX;m.ty=e.clientY},{passive:true});function go(){m.x+=(m.tx-m.x)*.05;m.y+=(m.ty-m.y)*.05;x.clearRect(0,0,w,h);for(const p of ps){let dx=m.x-p.x,dy=m.y-p.y,q=Math.hypot(dx,dy);if(q<140&&q>1){p.vx+=dx/q*.0006;p.vy+=dy/q*.0006}p.vx*=.9995;p.vy*=.9995;p.x+=p.vx;p.y+=p.vy;p.p+=.008;if(p.x<0)p.x=w;if(p.x>w)p.x=0;if(p.y<0)p.y=h;if(p.y>h)p.y=0;x.beginPath();x.arc(p.x,p.y,p.r,0,7);x.fillStyle='rgba(56,212,119,.25)';x.fill()}for(let i=0;i<ps.length;i++)for(let j=i+1;j<ps.length;j++){let a=ps[i],b=ps[j],q=Math.hypot(a.x-b.x,a.y-b.y);if(q<110){x.strokeStyle='rgba(56,212,119,'+(1-q/110)*.08+')';x.beginPath();x.moveTo(a.x,a.y);x.lineTo(b.x,b.y);x.stroke()}}requestAnimationFrame(go)}size();go()})()</script>'''

