def make_demo_page(slug,title,kind,desc,body):
    back='demos.html'
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — Eyasin Sheikh</title><style>{shared_css}.demo-page{{padding:55px}}.demo-head{{display:flex;justify-content:space-between;gap:25px;align-items:flex-end;margin-bottom:30px}}.demo-head h1{{font:600 clamp(40px,7vw,78px)/.9 'Space Grotesk';letter-spacing:-.08em;margin:10px 0}}.demo-head p{{max-width:580px;color:#777;font-size:12px;line-height:1.8}}.app{{border:1px solid #deded8;border-radius:8px;padding:28px;background:#fff;box-shadow:0 20px 60px #0001}}input,select,button,textarea{{font:inherit}}input,select,textarea{{width:100%;padding:12px;border:1px solid #ddd;border-radius:7px;background:#fafaf7}}button{{border:0;background:#171717;color:#fff;padding:12px 16px;border-radius:7px;cursor:pointer;transition:.4s var(--ease)}}button:hover{{transform:translateY(-2px);box-shadow:0 10px 24px #0002}}.row2{{display:grid;grid-template-columns:repeat(2,1fr);gap:15px;margin-bottom:15px}}.result{{margin-top:18px;padding:18px;border-radius:7px;background:#f0f0eb;font:600 22px 'Space Grotesk'}}.code{{margin-top:28px;background:#20201f;color:#eee;padding:20px;border-radius:8px;overflow:auto;font:12px/1.7 monospace;white-space:pre-wrap}}@media(max-width:700px){{.demo-page{{padding:24px}}.demo-head{{display:block}}.row2{{grid-template-columns:1fr}}}}</style></head><body>{particle}<main class="site"><section class="panel"><nav class="nav"><a class="back" href="{back}">← All Demos</a><a href="index.html">Eyasin Sheikh</a></nav><div class="demo-page"><div class="demo-head"><div><span class="eyebrow">{kind}</span><h1>{title}</h1></div><p>{desc}</p></div><div class="app">{body}</div><div class="code"># Python / project idea<br># This demo is an interactive browser version of the project.<br># The same logic can be implemented in Python with functions, classes and file/database storage.</div></div></section></main></body></html>'''

bodies={
'web-studio':'''<div class="row2"><input id="name" placeholder="Your name"><select id="theme"><option>Minimal</option><option>Neon</option><option>Sunset</option></select></div><textarea id="msg" rows="5" placeholder="Write a message..."></textarea><br><br><button onclick="preview()">Preview</button><div id="out" class="result">Your preview will appear here.</div><script>function preview(){out.innerHTML='<b>'+((name.value||'Eyasin').replaceAll('<','&lt;'))+'</b><br>'+((msg.value||'Welcome to my website.').replaceAll('<','&lt;'))+'<br><small>Theme: '+theme.value+'</small>'}</script>''',
'neon-shop':'''<div class="row2"><select id="item"><option value="49">Cyber Keyboard — $49</option><option value="79">RGB Headset — $79</option><option value="129">Creator Mouse — $129</option></select><input id="qty" type="number" min="1" value="1"></div><button onclick="add()">Add to Cart</button><div id="out" class="result">Cart: 0 items · $0</div><script>let total=0,count=0;function add(){let q=Math.max(1,+qty.value||1),p=+item.value;count+=q;total+=q*p;out.textContent='Cart: '+count+' items · $'+total.toFixed(2)}</script>''',
'focus-dashboard':'''<div class="row2"><input id="goal" type="number" min="1" value="8" placeholder="Daily focus goal"><input id="done" type="number" min="0" value="3" placeholder="Completed sessions"></div><button onclick="calc()">Update Dashboard</button><div id="out" class="result">Progress: 37.5%</div><script>function calc(){let g=Math.max(1,+goal.value||1),d=Math.max(0,+done.value||0),p=Math.min(100,d/g*100);out.innerHTML='Progress: '+p.toFixed(1)+'%<br><small>'+d+' of '+g+' focus sessions completed.</small>'}</script>''',
'python-expense':'''<div class="row2"><input id="income" type="number" placeholder="Income" value="1000"><input id="expense" type="number" placeholder="Expense" value="350"></div><button onclick="calc()">Analyze</button><div id="out" class="result">Balance: $650</div><script>function calc(){let i=+income.value||0,e=+expense.value||0;out.textContent='Balance: $'+(i-e).toFixed(2)+' · Savings rate: '+(i?((i-e)/i*100).toFixed(1):0)+'%'}</script>''',
'python-password':'''<div class="row2"><input id="pw" type="password" placeholder="Enter a password"><button onclick="analyze()">Analyze Strength</button></div><button onclick="generate()">Generate Strong Password</button><div id="out" class="result">Enter a password to begin.</div><script>function analyze(){let v=pw.value,s=0;s+=v.length>=8;s+=/[A-Z]/.test(v);s+=/[a-z]/.test(v);s+=/[0-9]/.test(v);s+=/[^A-Za-z0-9]/.test(v);out.textContent='Strength: '+['Very weak','Weak','Fair','Good','Strong','Excellent'][s]+' ('+s+'/5)'}function generate(){let a='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%';let r='';for(let i=0;i<14;i++)r+=a[Math.floor(Math.random()*a.length)];pw.value=r;analyze()}</script>''',
'python-student':'''<div class="row2"><input id="name" placeholder="Student name"><input id="marks" type="number" min="0" max="100" value="82" placeholder="Marks"></div><button onclick="result()">Calculate Result</button><div id="out" class="result">Enter marks.</div><script>function result(){let m=Math.max(0,Math.min(100,+marks.value||0));let g=m>=80?'A+':m>=70?'A':m>=60?'A-':m>=50?'B':m>=40?'C':m>=33?'D':'F';out.textContent=(name.value||'Student')+' · '+m+' marks · Grade '+g}</script>'''
}
