demos='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Demo Projects — Eyasin Sheikh</title><style>'''+shared_css+'''</style></head><body>'''+particle+'''<main class="site"><section class="panel"><nav class="nav"><a class="back" href="index.html">← Main Website</a><a href="index.html">Eyasin Sheikh</a></nav><div class="hero2"><span class="eyebrow">Second Landing Page</span><h1>DEMO<br>PROJECTS</h1><p>Three polished web projects and three practical Python projects. Each demo opens on its own landing page and includes a working interactive experience.</p><div class="filters"><button class="filter active" data-filter="all">All [6]</button><button class="filter" data-filter="web">Web Development [3]</button><button class="filter" data-filter="python">Python Programming [3]</button></div></div><div class="grid">'''+cards+'''</div><div class="footer">© 2026 Eyasin Sheikh · Still learning, acquiring skills and building.</div></section></main><script>const cards=[...document.querySelectorAll('.demo-card')],buttons=[...document.querySelectorAll('.filter')];function setFilter(f){cards.forEach(c=>c.classList.toggle('hidden',f!=='all'&&c.dataset.type!==f));buttons.forEach(b=>b.classList.toggle('active',b.dataset.filter===f))}buttons.forEach(b=>b.onclick=()=>setFilter(b.dataset.filter));const q=new URLSearchParams(location.search).get('type');if(q==='web'||q==='python')setFilter(q);</script></body></html>'''
